def link(path,text,cls='',external=False):
    attr=' target="_blank" rel="noopener"' if external else ''
    return f'<a href="{html.escape(path,quote=True)}" class="{cls}"{attr}>{text}</a>'
def arrow():return '<span aria-hidden="true">↗</span>'
def img(key,alt,cls='',eager=False):
    return f'<img src="{html.escape(images[key],quote=True)}" alt="{html.escape(alt,quote=True)}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def eyebrow(s):return '<p class="eyebrow">'+s+'</p>'
def cta(text='Find your first lesson',small='A little curiosity is all it takes.'):
    return '<section class="final-cta wrap"><div>'+eyebrow('Let’s make music')+'<h2>'+text+'</h2><p>'+small+'</p></div>'+link('trial-lesson.html','Choose a trial lesson '+arrow(),'button')+'</section>'
def faq(items):
    return '<div class="faq-list">'+''.join('<details><summary>'+html.escape(q)+'<span aria-hidden="true">+</span></summary><p>'+a+'</p></details>' for q,a in items)+'</div>'
def location_cards(mode='detail'):
    out='<div class="location-grid">'
    for i,l in enumerate(locations):
        href=l['booking'] if mode=='booking' else l['slug']+'.html'
        label='View '+l['name']+' trial times' if mode=='booking' else 'Explore '+l['name']
        out+=f'<article class="location-card"><span class="place-number">0{i+1}</span><div><p class="eyebrow">Studio lessons</p><h3>{l["name"]}</h3><p class="venue">{l["venue"]}</p><p>{l["address"]}<br>{l["city"]}</p>'+link(href,label+' '+arrow(),'text-link',mode=='booking')+'</div></article>'
    return out+'</div>'
def instrument_rows(limit=False):
    chosen=instruments[:2]+[instruments[4],instruments[6],instruments[-1]] if limit else instruments
    return '<div class="instrument-list">'+''.join('<a class="instrument-row" href="'+i['slug']+'.html"><span class="instrument-number">'+str(n+1).zfill(2)+'</span><div><h3>'+i['name']+'</h3><p>'+i['line']+'</p></div><span class="round-arrow" aria-hidden="true">↗</span></a>' for n,i in enumerate(chosen))+'</div>'
def mast(title,intro,kicker='FM Studios Music School'):
    return '<section class="page-mast wrap">'+eyebrow(kicker)+'<h1>'+title+'</h1><p class="lead">'+intro+'</p></section>'
def add(slug,title,description,body):pages.append({'slug':slug,'title':title,'description':description,'body':body})

